'use strict';
let customerOrders=[],orderRequest=0;
function updateOrderCurrency(){if(!customerOrders.length)return;$('revenueTotal').textContent=euros(customerOrders.reduce((sum,o)=>sum+o.cents,0));document.querySelectorAll('#orderList tbody tr').forEach((row,i)=>{const cell=row.children[3];if(cell&&customerOrders[i])cell.textContent=euros(customerOrders[i].cents);});}
const parisDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
$('revenueMonth').value=parisDate().slice(0,7);
function clearOrders(){orderRequest++;customerOrders=[];$('orderList').innerHTML='';$('revenueTotal').textContent='';$('orderCount').textContent='';$('ordersError').textContent='';}
async function loadOrders(){if(currentUser?.role!=='manager'){clearOrders();return;}const request=++orderRequest,month=$('revenueMonth').value;$('ordersError').textContent='';try{const result=await api('orders?month='+encodeURIComponent(month));if(request!==orderRequest||currentUser?.role!=='manager')return;customerOrders=result.orders;$('revenueTotal').textContent=euros(result.totalCents);$('orderCount').textContent=customerOrders.length+' đơn đã thanh toán';$('orderList').innerHTML=customerOrders.length?'<div class="table-wrap"><table><thead><tr><th>TÊN KHÁCH</th><th>NGÀY THANH TOÁN</th><th>NHÂN VIÊN</th><th>ĐÃ THANH TOÁN</th><th></th></tr></thead><tbody>'+customerOrders.map(o=>'<tr><td data-no-translate>'+esc(o.customer)+'</td><td>'+esc(o.paid_date)+'</td><td data-no-translate>'+esc(o.employee_name)+'</td><td>'+euros(o.cents)+'</td><td><button class="outline" data-order="'+esc(o.id)+'">Sửa đơn</button> <button class="outline" data-delete-order="'+esc(o.id)+'">Xóa đơn</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty"><p>Chưa có đơn khách trong tháng này.</p></div>';}catch(e){if(request!==orderRequest)return;customerOrders=[];$('orderList').innerHTML='';$('revenueTotal').textContent='—';$('orderCount').textContent='';$('ordersError').textContent=e.message;}}
function openOrder(id){if(currentUser?.role!=='manager')return;if(!state.employees.length){toast('Thêm hoặc duyệt nhân viên trước khi tạo đơn');return;}const order=customerOrders.find(o=>o.id===id),form=$('orderForm');form.reset();form.elements.id.value=order?.id||'';form.elements.customer.value=order?.customer||'';form.elements.amount.value=order?(order.cents/100).toFixed(2):'';form.elements.date.value=order?.paid_date||parisDate();form.elements.date.max=parisDate();form.elements.employee.innerHTML=state.employees.filter(e=>!e.deleted).map(e=>'<option value="'+esc(e.id)+'">'+esc(e.name)+'</option>').join('');form.elements.employee.value=order?.employee||state.employees[0].id;$('orderError').textContent='';$('orderDialog').showModal();}
$('addOrder').onclick=()=>openOrder();$('revenueMonth').onchange=loadOrders;$('orderList').onclick=async e=>{const remove=e.target.closest('[data-delete-order]');if(remove){if(!confirm(translateText('Xóa đơn này? Doanh thu sẽ được tính lại.')))return;remove.disabled=true;try{await api('delete',{type:'order',id:remove.dataset.deleteOrder});await loadOrders();toast('Đã xóa');}catch(error){toast(error.message);remove.disabled=false;}return;}const button=e.target.closest('[data-order]');if(button)openOrder(button.dataset.order);};
$('orderForm').onsubmit=async event=>{event.preventDefault();const f=event.target,b=f.querySelector('button.primary');b.disabled=true;$('orderError').textContent='';try{await api('orders',{id:f.elements.id.value,customer:f.elements.customer.value,employee:f.elements.employee.value,date:f.elements.date.value,amount:f.elements.amount.value});$('revenueMonth').value=f.elements.date.value.slice(0,7);$('orderDialog').close();await loadOrders();toast('Đã lưu đơn khách');}catch(e){$('orderError').textContent=e.message;}finally{b.disabled=false;}};
